export const requirementCount = requirementBindings.length;
export function getRequirementBinding(id:string): RequirementBinding { const binding=requirementBindings.find(x=>x.id===id); if(!binding) throw new Error(`Unknown requirement: ${id}`); return binding; }
export function getChapterBindings(chapter:number): readonly RequirementBinding[] { return requirementBindings.filter(x=>x.chapter===chapter); }
